import random

import pytest

from bwt import (
    bwt,
    ibwt,
    mtf_decode,
    mtf_encode,
    pipeline_compress,
    pipeline_decompress,
    rle_decode,
    rle_encode,
)

CORPUS = b"she sells seashells by the seashore " * 500


# ---------------------------------------------------------------- BWT core

def test_bwt_banana_classic_vector():
    # Sentinel-augmented rotation matrix for "banana$" sorts to rows
    # $, a$, ana$, anana$, banana$, na$, nana$  => last column annb$aa,
    # sentinel sits in row 4; stripped output below.
    assert bwt(b"banana") == (b"annbaa", 4)


def test_ibwt_inverts_banana():
    t, i = bwt(b"banana")
    assert ibwt(t, i) == b"banana"


@pytest.mark.parametrize(
    "data",
    [b"", b"a", b"ab" * 100, bytes(range(256)), b"\x00" * 50],
)
def test_bwt_edge_cases_round_trip(data):
    t, i = bwt(data)
    assert ibwt(t, i) == data


def test_bwt_300_seeded_random_inputs():
    rng = random.Random(20260824)
    for trial in range(300):
        size = rng.randrange(0, 5001)
        data = bytes(rng.randrange(256) for _ in range(size))
        t, i = bwt(data)
        assert ibwt(t, i) == data, f"round-trip failed at trial {trial}, size {size}"


# ------------------------------------------------------- MTF and RLE units

@pytest.mark.parametrize(
    "data",
    [b"", b"banana", bytes(range(256)), bytes(rng_seed()) if False else b"abcabcabc"],
)
def test_mtf_round_trip(data):
    assert mtf_decode(mtf_encode(data)) == data


def test_mtf_makes_small_values_for_repetitive_input():
    assert max(mtf_encode(b"aaaaaaaa")) == 1  # first 'a' is 97, rest map to 0


def test_rle_scheme_encoding_shape():
    assert rle_encode(b"aa") == b"aa"                      # short run literal
    assert rle_encode(b"aaaa") == b"\x00\x04a"             # run of 4 -> triple
    assert rle_encode(b"\x00") == b"\x00\x01\x00"          # escaped literal NUL
    assert rle_encode(b"\x00" * 10) == b"\x00\x0a\x00"     # NUL run
    long_run = b"x" * 300
    assert rle_encode(long_run) == b"\x00\xffx\x00Iy"      # 255 + 105 split


@pytest.mark.parametrize(
    "data",
    [b"", b"a", b"mississippi", bytes(range(256)), b"\x00\x00\x00zzz\x00"],
)
def test_rle_round_trip(data):
    assert rle_decode(rle_encode(data)) == data


# ------------------------------------------------------------ the payoff

def test_rle_alone_helper():
    # rle_alone is plain RLE without BWT/MTF, as referenced by the payoff test.
    assert isinstance(rle_alone(CORPUS), bytes)


def rle_alone(data: bytes) -> bytes:
    return rle_encode(data)


def test_pipeline_beats_rle_alone_on_repetitive_corpus():
    x = CORPUS
    compressed = pipeline_compress(x)
    alone = rle_alone(x)
    assert len(compressed) < 0.7 * len(alone), (
        f"payoff failed: pipeline {len(compressed)} vs 0.7 * rle-alone "
        f"{0.7 * len(alone)}"
    )


# ------------------------------------------------ whole-pipeline integrity

def test_pipeline_round_trip_corpus():
    assert pipeline_decompress(pipeline_compress(CORPUS)) == CORPUS


def test_pipeline_round_trip_random_inputs():
    rng = random.Random(42)
    for _ in range(30):
        size = rng.randrange(0, 2000)
        data = bytes(rng.randrange(256) for _ in range(size))
        assert pipeline_decompress(pipeline_compress(data)) == data


@pytest.fixture(scope="session", autouse=True)
def _report_payoff_numbers():
    yield
    x = CORPUS
    print(
        f"\npayoff: pipeline={len(pipeline_compress(x))} bytes, "
        f"rle-alone={len(rle_alone(x))} bytes"
    )

